8	func stripTrailingZeros(s string) string {
9		if !strings.ContainsRune(s, '.') {
10			return s
11		}
12		offset := len(s) - 1
13		for offset > 0 {
14			if s[offset] == '.' {
15				offset--
16				break
17			}
18			if s[offset] != '0' {
19				break
20			}
21			offset--
22		}
23		return s[:offset+1]
24	}
25	
26	func stripTrailingDigits(s string, digits int) string {
27		if i := strings.Index(s, "."); i >= 0 {
28			if digits <= 0 {
29				return s[:i]
30			}
31			i++
32			if digits >= len(s)-i {
33				return s
34			}
35			return s[:i+digits]
36		}
37		return s
38	}
